from collections import defaultdict, deque
class Solution:
    def maxRequests(self, requests, k, window):
        d = defaultdict(list)
        for u, t in requests: d[u].append(t)
        ans = 0
        for ts in d.values():
            ts.sort()
            q = deque()
            for t in ts:
                q.append(t)
                while len(q) > k and t - q[len(q) - 1 - k] <= window:
                    q.popleft()
            ans += len(q)
        return ans

