class Solution {
public:
    int maxRequests(vector<vector<int>>& requests, int k, int window) {
        unordered_map<int, vector<int>> d;
        for (auto& r : requests) d[r[0]].push_back(r[1]);
        int ans = 0;
        for (auto& [u, ts] : d) {
            sort(ts.begin(), ts.end());
            deque<int> q;
            for (int t : ts) {
                q.push_back(t);
                while ((int)q.size() > k && t - q[q.size() - 1 - k] <= window) q.pop_front();
            }
            ans += q.size();
        }
        return ans;
    }
};

