class Solution {
    public int maxRequests(int[][] requests, int k, int window) {
        Map<Integer, List<Integer>> d = new HashMap<>();
        for (int[] r : requests) d.computeIfAbsent(r[0], x -> new ArrayList<>()).add(r[1]);
        int ans = 0;
        for (List<Integer> list : d.values()) {
            Collections.sort(list);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            for (int t : list) {
                q.addLast(t);
                Iterator<Integer> it = q.iterator();
                while (q.size() > k) {
                    int oldest = q.peekFirst();
                    int idx = 0, val = 0;
                    for (int v : q) { if (idx == q.size() - 1 - k) { val = v; break; } idx++; }
                    if (t - val <= window) q.pollFirst(); else break;
                }
            }
            ans += q.size();
        }
        return ans;
    }
}

