var maxRequests = function(requests, k, window) {
    const d = new Map();
    for (const [u, t] of requests) {
        if (!d.has(u)) d.set(u, []);
        d.get(u).push(t);
    }
    let ans = 0;
    for (const ts of d.values()) {
        ts.sort((a, b) => a - b);
        const q = [];
        for (const t of ts) {
            q.push(t);
            while (q.length > k && t - q[q.length - 1 - k] <= window) q.shift();
        }
        ans += q.length;
    }
    return ans;
};
